import json
import math
import statistics
import sys
from pathlib import Path

out = Path(sys.argv[1])
dates = ["2024-03-04", "2024-03-05", "2024-03-06", "2024-03-07", "2024-03-08", "2024-03-11"]
closes = {
    "A": [100.0, 102.0, 101.0, 104.0, 103.0, 105.0],
    "B": [50.0, 51.0, 50.2, 49.6, 50.4, 51.2],
}
tickers = ["A", "B"]
prices = {"dates": dates, "tickers": tickers, "closes": closes}

rets = {t: [math.log(c[i] / c[i - 1]) for i in range(1, len(c))] for t, c in closes.items()}
returns = {"base_date": dates[0], "dates": dates[1:], "tickers": tickers, "values": rets}

window = 2
vols = {}
for t, r in rets.items():
    vols[t] = [
        None if i < window else statistics.stdev(r[i - window : i]) * math.sqrt(252)
        for i in range(len(r))
    ]
vol = {"returns": returns, "window": window, "annualized": True, "values": vols}


def summary(t):
    r = rets[t]
    ann_return = 252 * statistics.fmean(r)
    ann_vol = math.sqrt(252) * statistics.stdev(r)
    return {
        "ticker": t,
        "ann_return": ann_return,
        "ann_vol": ann_vol,
        "sharpe": ann_return / ann_vol if ann_vol else 0.0,
        "last_vol": vols[t][-1],
    }


def drawdown(t):
    wealth = [1.0]
    for x in rets[t]:
        wealth.append(wealth[-1] * math.exp(x))
    peak_i, best = 0, (0.0, 0, 0)
    for i, w in enumerate(wealth):
        if w > wealth[peak_i]:
            peak_i = i
        depth = w / wealth[peak_i] - 1
        if depth < best[0]:
            best = (depth, peak_i, i)
    return {"ticker": t, "depth": best[0], "peak_date": dates[best[1]], "trough_date": dates[best[2]]}


rows = []
for t in tickers:
    s, d = summary(t), drawdown(t)
    rows.append(
        {
            "ticker": t,
            "ann_return": s["ann_return"],
            "ann_vol": s["ann_vol"],
            "sharpe": s["sharpe"],
            "last_vol": s["last_vol"],
            "max_drawdown": d["depth"],
            "peak_date": d["peak_date"],
            "trough_date": d["trough_date"],
        }
    )

raw = {
    "rows": [
        {"date": "2024-03-04", "ticker": "A", "close": 100.0},
        {"date": "2024-03-04", "ticker": "B", "close": 50.0},
        {"date": "2024-03-05", "ticker": "B", "close": 51.0},
        {"date": "2024-03-05", "ticker": "A", "close": 102.0},
        {"date": "2024-03-06", "ticker": "A", "close": None},
        {"date": "2024-03-06", "ticker": "B", "close": 50.2},
        {"date": "2024-03-07", "ticker": "A", "close": 104.0},
        {"date": "2024-03-07", "ticker": "B", "close": 49.6},
    ]
}

files = {
    "mdata.RawRow": raw,
    "mdata.Prices": prices,
    "risk.Returns": returns,
    "risk.VolSeries": vol,
    "risk.TickerSummary": summary("A"),
    "risk.Drawdown": drawdown("B"),
    "risk.Report": {"path": "report.json", "rows": rows},
}
for name, payload in files.items():
    folder = out / name
    folder.mkdir(parents=True, exist_ok=True)
    (folder / "sample.json").write_text(json.dumps(payload, indent=2) + "\n")

csv = ["date,ticker,close"] + [f"{d},{t},{closes[t][i]}" for i, d in enumerate(dates) for t in tickers]
(out / "mdata.load_prices").mkdir(exist_ok=True)
(out / "mdata.load_prices" / "prices.csv").write_text("\n".join(csv) + "\n")
print(json.dumps(files["risk.Drawdown"]), json.dumps(files["risk.TickerSummary"]))

